static int
DeviceAccessCallback(void *data, ClientPtr client, int mode, int majorOp, int minorOp)
{
    DeviceAccessCallbackParam *param = (DeviceAccessCallbackParam *)data;

    if (!param)
        return Success;

    if (!client)
        return Success;

    if (SpatialSecurityPrivileged(client))
        return Success;

    if (!(mode & (DixManageAccess | DixBellAccess)))
        return Success;

    switch (majorOp) {
    case X_ChangeKeyboardMapping:
    case X_ChangeKeyboardControl:
    case X_Bell:
    case X_ChangePointerControl:
    case X_SetPointerMapping:
    case X_SetModifierMapping:
        return BadAccess;
    default:
        return Success;
    }
}
